import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.f7HpIP93.js";var i=JSON.parse(`{"title":"Supply-Chain Security Posture","description":"","frontmatter":{},"headers":[],"relativePath":"supply-chain.md","filePath":"supply-chain.md","lastUpdated":1785679185000}`),a={name:`supply-chain.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="supply-chain-security-posture" tabindex="-1">Supply-Chain Security Posture <a class="header-anchor" href="#supply-chain-security-posture" aria-label="Permalink to “Supply-Chain Security Posture”">​</a></h1><p>This document maps every supply-chain and security control in the Glaucus repository to the mechanism that implements it and where it runs.</p><h2 id="control-matrix" tabindex="-1">Control Matrix <a class="header-anchor" href="#control-matrix" aria-label="Permalink to “Control Matrix”">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Mechanism</th><th>Local mise run target</th><th>CI job / workflow</th></tr></thead><tbody><tr><td><strong>Memory safety</strong></td><td><code>#![forbid(unsafe_code)]</code> on glaucus-core / glaucus-ast / glaucus-cst; Miri with <code>-Zmiri-strict-provenance</code></td><td><code>mise run miri</code></td><td><code>nightly.yml</code> — <code>miri</code> job</td></tr><tr><td><strong>Dependency advisories</strong></td><td><code>cargo audit</code> against the RustSec advisory database</td><td><code>mise run audit</code></td><td><code>ci.yml</code> — <code>supply-chain</code> job</td></tr><tr><td><strong>License &amp; ban policy</strong></td><td><code>cargo deny check</code> (licenses allowlist, multiple-versions ban, unknown-registries ban)</td><td><code>mise run deny</code></td><td><code>ci.yml</code> — <code>supply-chain</code> job</td></tr><tr><td><strong>Supply-chain audits</strong></td><td><code>cargo vet</code> — audit records in <code>supply-chain/audits.toml</code>; non-blocking until tree is certified</td><td><code>mise run vet</code></td><td><code>ci.yml</code> — <code>vet</code> job (continue-on-error)</td></tr><tr><td><strong>Build provenance</strong></td><td>SLSA Level 3 via <code>slsa-framework/slsa-github-generator</code></td><td>CI only</td><td><code>release.yml</code> — <code>provenance</code> job</td></tr><tr><td><strong>Artifact signing</strong></td><td>sigstore/cosign keyless signing (<code>.cosign.bundle</code> per artifact)</td><td>CI only</td><td><code>release.yml</code> — <code>sign</code> job</td></tr><tr><td><strong>Project scorecard</strong></td><td>OpenSSF Scorecard (<code>ossf/scorecard-action</code>); weekly schedule</td><td>CI only</td><td><code>scorecard.yml</code> — <code>analysis</code> job</td></tr><tr><td><strong>License compliance</strong></td><td>REUSE 3.3 — every file covered via <code>REUSE.toml</code> globs + <code>LICENSES/</code> directory</td><td><code>mise run reuse</code></td><td><em>(run <code>reuse lint</code> locally; CI integration pending)</em></td></tr><tr><td><strong>Fuzzing</strong></td><td>8 <code>cargo-fuzz</code> targets: <code>fuzz_scanner</code>, <code>fuzz_parser</code>, <code>fuzz_round_trip</code>, <code>fuzz_limits</code>, <code>fuzz_serde</code>, <code>fuzz_cst_roundtrip</code>, <code>fuzz_lossless_edit</code>, <code>fuzz_merge_keys</code></td><td><code>mise run fuzz-all</code></td><td><code>nightly.yml</code> — <code>fuzz</code> job</td></tr><tr><td><strong>Test coverage</strong></td><td><code>cargo-tarpaulin</code> with LLVM engine; 100% line coverage required (<code>--fail-under 100</code>)</td><td><code>mise run coverage</code></td><td><code>ci.yml</code> — <code>coverage</code> job (macOS runner)</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><p><strong>Ordering in supply-chain job</strong> — <code>cargo audit</code> intentionally runs before <code>cargo deny</code> in <code>ci.yml</code>. <code>cargo audit</code> clones the RustSec advisory database into <code>~/.cargo/advisory-db</code>; <code>cargo deny</code>&#39;s <code>advisories</code> check reuses that directory and will fail if it is non-empty when the clone is attempted.</p><p><strong>cargo vet is non-blocking</strong> — the <code>vet</code> job in <code>ci.yml</code> carries <code>continue-on-error: true</code> until the dependency audit set is fully populated with <code>cargo vet certify</code> entries. Remove that flag once the tree is audited.</p><p><strong>REUSE compliance</strong> — <code>REUSE.toml</code> uses glob patterns to cover every file class (Rust sources carry SPDX headers inline; config files, docs, and CI workflows are covered by catch-all globs). Run <code>reuse lint</code> or <code>mise run reuse</code> to verify compliance locally.</p><p><strong>SLSA / cosign are release-only</strong> — these controls run on tag pushes (<code>on: push: tags: [&#39;v*&#39;]</code>) and are not part of the PR gate. They operate on the published <code>.tar.gz</code> / <code>.sha256</code> release assets.</p><p><strong>Miri scope</strong> — Miri tests <code>glaucus-core</code> and <code>glaucus-ast</code>. <code>glaucus-serde</code> and <code>glaucus-cst</code> pull in <code>serde</code> proc-macros which Miri does not yet fully support; they are intentionally excluded.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};